patches.find:
function ldWelFirstName(full) {
    var n = String(full || '').trim();
    if (!n) return '';
    return n.split(/\s+/)[0];
  }
  function ldWelTemplates(l, lang) {
    var name = ldWelFirstName(l.full_name) || (lang === 'EN' ? 'there' : '');
    var greet = lang === 'EN'
      ? ('Dear ' + (name === 'there' ? 'Owner' : name) + ',')
      : ('Αγαπητέ/ή' + (name ? (' ' + name) : '') + ',');
    var subject = lang === 'EN'
      ? 'Welcome to Elysian Properties'
      : 'Καλωσήρθατε στην Elysian Properties';
    var body = lang === 'EN'
      ? (greet + '\n\n'
        + 'Thank you for your interest in property management with Elysian Properties.\n\n'
        + 'Please find attached our company brochure with the management packages we offer '
        + '(Essential, Signature and Elite) and the hospitality services behind them — '
        + 'dynamic pricing, 24/7 guest support, professional cleaning and transparent pass-through costs.\n\n'
        + 'We would be glad to schedule a short call to discuss your property and the right package.\n\n'
        + 'Kind regards,\n'
        + 'Elysian Properties\n'
        + '+30 210 260 2749\n'
        + 'info@elysianproperties.eu\n'
        + 'elysianproperties.eu')
      : (greet + '\n\n'
        + 'Σας ευχαριστούμε για το ενδιαφέρον σας για τη διαχείριση του ακινήτου σας με την Elysian Properties.\n\n'
        + 'Επισυνάπτουμε το εταιρικό μας brochure με τα πακέτα διαχείρισης (Essential, Signature και Elite) '
        + 'και τις υπηρεσίες φιλοξενίας που προσφέρουμε — δυναμική τιμολόγηση, 24/7 εξυπηρέτηση επισκεπτών, '
        + 'επαγγελματική καθαριότητα και διαφανές μοντέλο κόστους χωρίς markup.\n\n'
        + 'Θα χαρούμε να κανονίσουμε μια σύντομη κλήση για να δούμε μαζί τις ανάγκες του ακινήτου σας.\n\n'
        + 'Με εκτίμηση,\n'
        + 'Elysian Properties\n'
        + '+30 210 260 2749\n'
        + 'info@elysianproperties.eu\n'
        + 'elysianproperties.eu');
    return { subject: subject, body: body };
  }

patches.replace:
function ldWelDisplayName(l) {
    var raw = (l && l.full_name) || '';
    if (typeof prettyPerson === 'function') {
      var p = prettyPerson(raw);
      if (p) return p;
    }
    return String(raw || '').replace(/[\u0000-\u001F\u007F]+/g, ' ').trim().replace(/\s+/g, ' ');
  }
  function ldWelFirstName(full) {
    var n = String(full || '').trim();
    if (!n) return '';
    var parts = n.split(/\s+/);
    var skip = { mr: 1, mrs: 1, ms: 1, miss: 1, dr: 1, 'κ': 1, 'κα': 1, 'κος': 1, 'κυριος': 1, 'κύριος': 1, 'κυρία': 1, 'κυρια': 1 };
    for (var i = 0; i < parts.length; i++) {
      var t = parts[i].replace(/[.\u0387]/g, '').toLowerCase();
      if (!skip[t]) return parts[i];
    }
    return parts[0];
  }
  function ldWelTemplates(l, lang) {
    var display = ldWelDisplayName(l);
    var first = ldWelFirstName(display);
    var greet = lang === 'EN'
      ? ('Dear ' + (first || 'Owner') + ',')
      : ('Αγαπητέ/ή' + (first ? (' ' + first) : '') + ',');
    var subject = lang === 'EN'
      ? (first ? ('Welcome to Elysian Properties, ' + first) : 'Welcome to Elysian Properties')
      : (first ? ('Καλωσήρθατε στην Elysian Properties, ' + first) : 'Καλωσήρθατε στην Elysian Properties');
    var where = [l.property_address, l.property_size].filter(Boolean).join(', ');
    var body = lang === 'EN'
      ? (greet + '\n\n'
        + (first ? ('Thank you, ' + first + ', for your interest in property management with Elysian Properties.')
                 : 'Thank you for your interest in property management with Elysian Properties.')
        + (where ? (' We noted your property at ' + where + '.') : '')
        + '\n\n'
        + 'Please find attached our company brochure with the management packages we offer '
        + '(Essential, Signature and Elite) and the hospitality services behind them — '
        + 'dynamic pricing, 24/7 guest support, professional cleaning and transparent pass-through costs.\n\n'
        + (first
            ? ('We would be glad to schedule a short call with you, ' + first + ', to discuss the right package for your property.\n\n')
            : 'We would be glad to schedule a short call to discuss your property and the right package.\n\n')
        + 'Kind regards,\n'
        + 'Elysian Properties\n'
        + '+30 210 260 2749\n'
        + 'info@elysianproperties.eu\n'
        + 'elysianproperties.eu')
      : (greet + '\n\n'
        + (first ? ('Σας ευχαριστούμε, ' + first + ', για το ενδιαφέρον σας για τη διαχείριση του ακινήτου σας με την Elysian Properties.')
                 : 'Σας ευχαριστούμε για το ενδιαφέρον σας για τη διαχείριση του ακινήτου σας με την Elysian Properties.')
        + (where ? (' Καταγράψαμε το ακίνητό σας στο ' + where + '.') : '')
        + '\n\n'
        + 'Επισυνάπτουμε το εταιρικό μας brochure με τα πακέτα διαχείρισης (Essential, Signature και Elite) '
        + 'και τις υπηρεσίες φιλοξενίας που προσφέρουμε — δυναμική τιμολόγηση, 24/7 εξυπηρέτηση επισκεπτών, '
        + 'επαγγελματική καθαριότητα και διαφανές μοντέλο κόστους χωρίς markup.\n\n'
        + (first
            ? ('Θα χαρούμε να κανονίσουμε μια σύντομη κλήση μαζί σας, ' + first + ', για να δούμε το κατάλληλο πακέτο για το ακίνητό σας.\n\n')
            : 'Θα χαρούμε να κανονίσουμε μια σύντομη κλήση για να δούμε μαζί τις ανάγκες του ακινήτου σας.\n\n')
        + 'Με εκτίμηση,\n'
        + 'Elysian Properties\n'
        + '+30 210 260 2749\n'
        + 'info@elysianproperties.eu\n'
        + 'elysianproperties.eu');
    return { subject: subject, body: body, displayName: display, firstName: first };
  }
